struct pollfd pfd = { .fd = chan_fd, .events = POLLIN };
for (;;) {
    int n = poll(&pfd, 1, idle_ms);            /* 0 = idle tick, -1/EINTR = retry */
    if (n > 0 && (pfd.revents & POLLIN)) {
        for (int i = 0; i < max_batch && read_msg(buf, sizeof buf) > 0; i++)
            handle(buf);                       /* ack: the message left the channel */
    } else {
        backoff(&state);                       /* explicit idle policy, no hot spin */
    }
}
